import type { SidebarsConfig } from '@docusaurus/plugin-content-docs';

/**
 * One sidebar per audience, because they share no pages: somebody running curator for their TVs,
 * and somebody working on it.
 *
 * Listed by hand rather than autogenerated: the order is an argument rather than an accident, and a
 * list here fails the build when a page is renamed instead of quietly moving it. The `develop/`
 * pages are copied in by `scripts/docs.sync.mjs`; their ids are the `doc` paths in its list.
 */
const sidebars: SidebarsConfig = {
    run: ['quick-start', 'using'],
    build: ['develop/index', 'develop/api', 'develop/web', 'develop/frame'],
};

export default sidebars;
